<?php
require_once 'auth_check.php'; require_once __DIR__ . '/app/partials.php'; $conn=getDBConnection(); $logs=$conn->query('SELECT admin_username,action_type,entity_type,entity_id,details,created_at FROM admin_audit_logs ORDER BY created_at DESC,audit_id DESC LIMIT 200');
