<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Log</title><link rel="stylesheet" href="css/addashb.css"><style>.main-content{margin-left:250px;padding:24px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border:1px solid #ddd;text-align:left}</style></head><body><div class="dashboard-container"><?php render_admin_sidebar('audit'); ?><main class="main-content"><h1>Audit Log</h1><p>Latest 200 administrator actions that affect donation records.</p><div class="table-wrap"><table><tr><th>Time</th><th>Admin</th><th>Action</th><th>Record</th><th>Details</th></tr><?php while($row=$logs->fetch_assoc()): ?><tr><td><?=e($row['created_at'])?></td><td><?=e($row['admin_username'])?></td><td><?=e($row['action_type'])?></td><td><?=e($row['entity_type'].' #'.$row['entity_id'])?></td><td><?=e($row['details'])?></td></tr><?php endwhile;?></table></div></main></div></body></html><?php $conn->close(); ?>
